I suggest removing the Promise/task types from this commit. Instead, use existing abstractions such as sdbubsplus::task or boost::awaitable, so the code can focus on the spdms aspects.

In general, coroutines should improve code readability, not complicate it.

For example, SPDM interactions with multiple devices can be structured as follows:

```
std::vector<spdm::device> devices = spdm::discoverDevices();
std::map<std::string,bool> deviceStatus;
boost::asio::io_context ctx;
for(auto device : devices) {
    ctx.spawn([device,&deviceStatus]() -> boost::awaitable<void> {
        spdm::context spdmContext;

        // Perform SPDM interaction with the device
        co_await spdm::initialize(spdmContext,device);
        auto ec =co_await spdm::performHandshake(spdmContext);
        if(ec) {
            deviceStatus[device.getName()] = false; // Mark as failed
            co_return;
        }
        auto [ec,measeaurments]= co_await spdm::takeMeasurments(spdmContext);
        if(ec) {
            deviceStatus[device.getName()] = false; // Mark as failed
            co_return;
        }
        deviceStatus[device.getName()] = validateMeasurements(measeaurments); 
    });
}
ctx.spawn([]()-> boost::awaitable<void>{
    while(deviceStatus.size() < devices.size()) {
        co_await boost::steady_timer(ctx,std::chrono::milliseconds(100)).async_wait();
    }
    std::cout << "All devices processed." << std::endl;
    for(const auto& [deviceName, status] : deviceStatus) {
        std::cout << "Device: " << deviceName << " Status: " << (status ? "OK" : "Failed") << std::endl;
    }
});
ctx.run();
